-- Focus / move / resize: vim keys and arrows
local dirs = {
  { keys = { "H", "left" }, dir = "left", dx = -40, dy = 0 },
  { keys = { "J", "down" }, dir = "down", dx = 0, dy = 40 },
  { keys = { "K", "up" }, dir = "up", dx = 0, dy = -40 },
  { keys = { "L", "right" }, dir = "right", dx = 40, dy = 0 },
}
for _, d in ipairs(dirs) do
  for _, key in ipairs(d.keys) do
    hl.bind(mainMod .. " + " .. key, hl.dsp.focus({ direction = d.dir }), { description = "Focus " .. d.dir })
    hl.bind(
      mainMod .. " + SHIFT + " .. key,
      hl.dsp.window.move({ direction = d.dir }),
      { description = "Move window " .. d.dir }
    )
    hl.bind(
      mainMod .. " + CTRL + " .. key,
      hl.dsp.window.resize({ x = d.dx, y = d.dy, relative = true }),
      { repeating = true, description = "Resize window " .. d.dir }
    )
  end
end

