-- Lid: turn the laptop screen off/on, only while an external monitor is connected
hl.bind("switch:on:Lid Switch", function()
  if #hl.get_monitors() > 1 then hl.monitor({ output = "eDP-1", disabled = true }) end
end, { locked = true, description = "Lid closed: disable laptop screen" })
hl.bind(
  "switch:off:Lid Switch",
  function() hl.monitor({ output = "eDP-1", disabled = false, mode = "preferred", position = "0x0", scale = 1 }) end,
  { locked = true, description = "Lid opened: enable laptop screen" }
)

-- Layouts (qtile: MonadTall -> master, Columns -> scrolling), per workspace
local layouts = { "dwindle", "master", "scrolling" }
local layoutRules = {}
local function cycleLayout(step)
  local ws = hl.get_active_workspace()
  if not ws then return end
  local nextLayout = layouts[1]
  for i, name in ipairs(layouts) do
    if name == ws.tiled_layout then nextLayout = layouts[(i - 1 + step) % #layouts + 1] end
  end
  if layoutRules[ws.id] then layoutRules[ws.id]:set_enabled(false) end
  layoutRules[ws.id] = hl.workspace_rule({ workspace = tostring(ws.id), layout = nextLayout })
  hl.notification.create({ text = "Layout: " .. nextLayout, timeout = 1500 })
end
hl.bind(mainMod .. " + SPACE", function() cycleLayout(1) end, { description = "Next layout" })
hl.bind(mainMod .. " + SHIFT + SPACE", function() cycleLayout(-1) end, { description = "Previous layout" })

-- Master layout: swap focused window with master (qtile/dwm "zoom")
hl.bind(mainMod .. " + CTRL + Return", hl.dsp.layout("swapwithmaster"), { description = "Swap with master" })

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
  local key = i % 10 -- 10 maps to key 0
  hl.bind(mainMod .. " + " .. key, hl.dsp.focus({ workspace = i }), { description = "Go to workspace " .. i })
  -- hl.bind(mainMod .. " + " .. key, hl.dsp.focus({ workspace = i, on_current_monitor = true }), { description = "Go to workspace " .. i })
  hl.bind(
    mainMod .. " + SHIFT + " .. key,
    hl.dsp.window.move({ workspace = i, follow = true }),
    { description = "Move window to workspace " .. i .. " and follow" }
  )
  hl.bind(
    mainMod .. " + CTRL + " .. key,
    hl.dsp.window.move({ workspace = i, follow = false }),
    { description = "Move window to workspace " .. i }
  )
end

